import { FieldValues, RegisterOptions } from 'react-hook-form';
import i18n from '~/shared/i18n/i18n';

export const createFormOptions = <T extends FieldValues>(overrides?: Partial<Record<string, RegisterOptions<T>>>) => {
  const defaultOptions: Partial<Record<string, RegisterOptions<T>>> = {
    NAME: {
      required: i18n.t('validation:enterNamePrompt'),
      pattern: { value: /^[가-힣]{2,}$/, message: i18n.t('validation:enterAtLeastTwoCharacters') },
    },
    BIRTH: {
      minLength: { value: 8, message: i18n.t('validation:enterBirthdateIn8Digits') },
      pattern: {
        value: /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])$/,
        message: i18n.t('validation:enterBirthdateInCorrectFormat'),
      },
      validate: {
        isBeforeToday: (value: string | null | undefined) => {
          if (!value) return i18n.t('validation:enterBirthdate');
          const birthDate = new Date(
            Number(value.slice(0, 4)),
            Number(value.slice(4, 6)) - 1,
            Number(value.slice(6, 8)),
          );
          const today = new Date();
          today.setHours(0, 0, 0, 0);
          return birthDate < today || i18n.t('validation:enterDateBeforeToday');
        },
      },
      required: i18n.t('validation:enterBirthdate'),
    },
    CARRIER: {
      required: '',
    },
    PHONE: {
      required: i18n.t('validation:enterPhoneNumber'),
      pattern: { value: /^01[016789][0-9]{7,8}$/, message: i18n.t('validation:invalidPhoneNumberFormat') },
    },
    BANK_ACCOUNT: {
      required: i18n.t('validation:enterNumber'),
      pattern: { value: /^[0-9]+$/, message: i18n.t('validation:numbersOnlyAllowed') },
    },
    BANK_CODE: {
      required: i18n.t('validation:chooseCategory'),
    },
    ALIAS_NM: {
      required: i18n.t('validation:enterWalletAddress'),
      pattern: { value: /^[0-9]+$/, message: i18n.t('validation:numbersOnlyAllowed') },
    },
    BUSINESS_NUMBER: {
      required: true,
      pattern: { value: /^[0-9]+$/, message: i18n.t('validation:numbersOnlyAllowed') },
    },
  };
  return {
    ...defaultOptions,
    ...overrides,
  };
};

export const MAX_INPUT_NUMBER = 999999999999999;
